import copy

def step(grid: list[list[int]], action: int, x: int = -1, y: int = -1) -> list[list[int]]:
    """
    Simulates one step of the grid game.

    Rules inferred:
    1. Action 6 is a click at (x, y).
    2. The game maintains a counter on the leftmost column (column 0).
       Each click increments this counter by changing the first 0 in column 0 to 5.
    3. The main gameplay involves swapping the color of the clicked connected component
       with the color 0 (black). This is a global swap: all cells of the clicked color
       become 0, and all cells of color 0 become the clicked color.
    """
    new_grid = copy.deepcopy(grid)

    if action == 6:
        # 1. Update counter on left column: find first 0 and change to 5
        for r in range(64):
            if new_grid[r][0] == 0:
                new_grid[r][0] = 5
                break

        # 2. Swap clicked component's color with 0
        if 0 <= x < 64 and 0 <= y < 64:
            color = new_grid[y][x]
            if color != 0:
                # Global swap: all cells of 'color' become 0, all cells of 0 become 'color'
                for r in range(64):
                    for c in range(64):
                        if new_grid[r][c] == color:
                            new_grid[r][c] = 0
                        elif new_grid[r][c] == 0:
                            new_grid[r][c] = color

    return new_grid

def goal(grid: list[list[int]]) -> bool:
    """
    Returns True if the level is completed.

    Hypothesis: The level is completed when the leftmost column is entirely filled with 5s.
    """
    for r in range(64):
        if grid[r][0] != 5:
            return False
    return True
